public sealed partial class LabExtractionService(AppDbContext dbContext, ICurrentUser currentUser, IEnumerable<IAgent> agents, ILabExtractionQueue queue, IConfiguration? configuration = null) : ILabExtractionService
{
    // Server-owned budget for one read ("Ocr:TotalTimeoutSeconds", default 150, clamped 10-600). It starts when the
    // background worker starts the read, not when the report is queued. "Ocr:TimeoutSeconds" is the per-process limit in TesseractOcrService.
    public TimeSpan OcrTimeout { get; init; } = TimeSpan.FromSeconds(Math.Clamp(
        int.TryParse(configuration?["Ocr:TotalTimeoutSeconds"], out var seconds) ? seconds : 150, 10, 600));

    public async Task<LabExtractionResultDto> ExtractAsync(Guid reportId, CancellationToken cancellationToken)
    {
        var report = await dbContext.LabReports.Include(x => x.Values).SingleOrDefaultAsync(x => x.Id == reportId, cancellationToken)
            ?? throw new NotFoundException();
        if (currentUser.UserType != UserType.FamilyUser) throw new NotFoundException();
        var member = await dbContext.Members.AsNoTracking().SingleAsync(x => x.Id == report.MemberId, cancellationToken);
        var isSelf = member.UserId == currentUser.UserId;
        var isMinor = member.DateOfBirth.AddYears(18) > DateOnly.FromDateTime(DateTime.UtcNow);
        var isHead = await dbContext.Families.AsNoTracking().Where(x => x.Id == member.FamilyId).AnyAsync(FamilyAccess.HeadedBy(currentUser.UserId), cancellationToken);
        if (!isSelf && !(isMinor && isHead)) throw new NotFoundException();
        if (!isSelf)
        {
            var consent = await dbContext.Consents.AsNoTracking().SingleOrDefaultAsync(x =>
                x.MemberId == member.Id && x.Category == ConsentCategory.Conditions &&
                x.Status == ConsentStatus.Granted && x.GrantedByGuardian,
                cancellationToken) ?? throw new NotFoundException();
            dbContext.AuditLogs.Add(new AuditLog
            {
                ActorUserId = currentUser.UserId,
                SubjectMemberId = member.Id,
                ConsentRefId = consent.Id,
                EventType = "GUARDIAN_CLINICAL_ACCESS",
                ResourceType = "LabReport",
                ResourceId = report.Id,
                Outcome = "SUCCESS",
                MetadataJson = "{}"
            });
            await dbContext.SaveChangesAsync(cancellationToken);
        }
        if (report.Values.Any(x => x.WasManuallyConfirmed) ||
            await dbContext.HereditaryFlags.AnyAsync(x => x.LabReportId == reportId && x.ManuallyConfirmed, cancellationToken))
            throw new ConflictException("A manually reviewed report cannot be extracted again.");
        // A read cut off by a crash stays "Processing"; after the stale window it may be retried.
        if (report.OcrStatus == OcrStatus.Processing && DateTimeOffset.UtcNow - report.UpdatedAt < OcrFailureCodes.StaleProcessingAfter)
            throw new ConflictException("OCR is already processing this report.");
        report.OcrStatus = OcrStatus.Processing;
        report.OcrErrorCode = null;
        try
        {
            await dbContext.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateConcurrencyException)
        {
            dbContext.ChangeTracker.Clear();
            throw new ConflictException("OCR is already processing this report.");
        }
        // Queued, not run: Tesseract on a 0.1-CPU host takes minutes and must not hold the HTTP request.
        // The queue is unbounded, so this never waits; a client disconnect after this point cannot cancel the read.
        await queue.QueueAsync(report.Id, CancellationToken.None);
        return new LabExtractionResultDto(report.Id, OcrStatus.Processing, 0, 0, true);
    }

    public static IReadOnlyList<ParsedLabValue> ParseValues(string text)
    {
        var values = text.Split('\n')
            .Select(line => LabValueLine().Match(line.Trim())).Where(match => match.Success && !DateInAnalyte().IsMatch(match.Groups["name"].Value) &&
                match.Groups["unit"].Value is not ("AM" or "AM." or "PM" or "PM."))
            .Select(match => new ParsedLabValue(match.Groups["name"].Value.Trim(),
                decimal.Parse(match.Groups["value"].Value, CultureInfo.InvariantCulture), match.Groups["unit"].Value,
                ParseNullable(match.Groups["low"].Value), ParseNullable(match.Groups["high"].Value)))
            .Take(200).ToList();
        if (values.Count == 200) return values;

        var lines = text.Split('\n').Select(line => line.Trim()).Where(line => line.Length > 0).ToList();
        for (var index = 0; index <= lines.Count - TableHeaderColumns.Length; index++)
        {
            if (!HasTableHeader(lines, index)) continue;
            index += TableHeaderColumns.Length;
            while (index + 5 < lines.Count && values.Count < 200)
            {
                if (HasTableHeader(lines, index) || HasTableHeader(lines, index + 1)) break;
                if (TryParseTableRow(lines, index, out var value)) values.Add(value);
                index += 6;
            }
            index--;
        }

        // Real OCR output keeps each table row on one line; the block above only covers one-cell-per-line text.
        var inlineHeaderSeen = false;
        foreach (var line in lines)
        {
            if (values.Count >= 200) break;
            var normalized = NormalizeTableText(line);
            if (InlineTableHeader().IsMatch(normalized)) { inlineHeaderSeen = true; continue; }
            if (inlineHeaderSeen && TryParseInlineTableRow(normalized, out var value)) values.Add(value);
        }

        // Result / unit / reference-range layout: no previous-result or date columns, range may be "Not supplied".
        var rangeHeaderSeen = false;
        foreach (var line in lines)
        {
            if (values.Count >= 200) break;
            var normalized = NormalizeTableText(line.TrimStart('|', ' '));
            if (RangeTableHeader().IsMatch(normalized)) { rangeHeaderSeen = true; continue; }
            if (rangeHeaderSeen && TryParseRangeTableRow(normalized, out var value)) values.Add(value);
        }

        // Column-aligned layout (PDF text layer, most local lab formats): cells are separated by two or more spaces.
        // Header wording varies per laboratory, so rows are matched by shape and analytes found above are not repeated.
        var seen = values.Select(x => x.Analyte).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (var line in text.Split('\n'))
        {
            if (values.Count >= 200) break;
            if (TryParseLayoutRow(CleanOcrDigits(line.Trim().TrimStart('|', ' ')), out var value) && seen.Add(value.Analyte)) values.Add(value);
        }
        return values;
    }

    private static bool TryParseLayoutRow(string line, out ParsedLabValue value)
    {
        value = default!;
        var row = LayoutRow().Match(line);
        if (!row.Success || DateInAnalyte().IsMatch(row.Groups["name"].Value) || QuestionnaireRow().IsMatch(row.Groups["name"].Value) ||
            NonAnalyteLabel().IsMatch(row.Groups["name"].Value) || !TryParseInvariantDecimal(row.Groups["value"].Value, out var current)) return false;
        decimal? low = null;
        decimal? high = null;
        if (row.Groups["low"].Success)
        {
            if (!TryParseInvariantDecimal(row.Groups["low"].Value, out var parsedLow) ||
                !TryParseInvariantDecimal(row.Groups["high"].Value, out var parsedHigh) || parsedLow > parsedHigh) return false;
            low = parsedLow;
            high = parsedHigh;
        }
        value = new ParsedLabValue(Regex.Replace(row.Groups["name"].Value.Trim(), @"\s+", " "), current, row.Groups["unit"].Value, low, high);
        return true;
    }

    // Fixes common OCR digit confusions inside numbers only: "1O.5" -> "10.5", "4,500" -> "4500", "12,4" -> "12.4".
    public static string CleanOcrDigits(string line)
    {
        var cleaned = OcrLetterInNumber().Replace(line, "0");
        cleaned = ThousandsSeparator().Replace(cleaned, "");
        return DecimalComma().Replace(cleaned, ".");
    }

    private static bool TryParseRangeTableRow(string line, out ParsedLabValue value)
    {
        value = default!;
        var row = RangeTableRow().Match(line);
        if (!row.Success || QuestionnaireRow().IsMatch(row.Groups["name"].Value) ||
            !TryParseInvariantDecimal(row.Groups["value"].Value, out var current)) return false;
        decimal? low = null;
        decimal? high = null;
        if (row.Groups["low"].Success)
        {
            if (!TryParseInvariantDecimal(row.Groups["low"].Value, out var parsedLow) ||
                !TryParseInvariantDecimal(row.Groups["high"].Value, out var parsedHigh)) return false;
            low = parsedLow;
            high = parsedHigh;
        }
        value = new ParsedLabValue(row.Groups["name"].Value.Trim(), current, row.Groups["unit"].Value, low, high);
        return true;
    }

    private static bool TryParseInlineTableRow(string line, out ParsedLabValue value)
    {
        value = default!;
        var row = InlineTableRow().Match(line);
        if (!row.Success || !TryParseInvariantDecimal(row.Groups["value"].Value, out var current) ||
            !DateOnly.TryParseExact(row.Groups["date"].Value, "MM/dd/yyyy", CultureInfo.InvariantCulture, DateTimeStyles.None, out _)) return false;
        decimal? low = null;
        decimal? high = null;
        if (row.Groups["low"].Success)
        {
            if (!TryParseInvariantDecimal(row.Groups["low"].Value, out var parsedLow) ||
                !TryParseInvariantDecimal(row.Groups["high"].Value, out var parsedHigh)) return false;
            low = parsedLow;
            high = parsedHigh;
        }
        value = new ParsedLabValue(row.Groups["name"].Value.Trim(), current, row.Groups["unit"].Value, low, high);
        return true;
    }

    public static IReadOnlyList<ParsedFlag> ParseFlags(string text) => text.Split('\n')
        .Select(line => FlagLine().Match(line.Trim())).Where(match => match.Success)
        .Select(match => new ParsedFlag(match.Groups["code"].Value.ToUpperInvariant(), match.Groups["finding"].Value.Trim(),
            Math.Clamp(decimal.Parse(match.Groups["confidence"].Value, CultureInfo.InvariantCulture), 0m, 1m)))
        .Take(20).ToList();

    private static decimal? ParseNullable(string value) => string.IsNullOrWhiteSpace(value) ? null : decimal.Parse(value, CultureInfo.InvariantCulture);

    private static readonly string[] TableHeaderColumns = ["Test", "Result", "Previous Result", "Date", "Units", "Ref Interval"];

    private static bool HasTableHeader(IReadOnlyList<string> lines, int index) =>
        index + TableHeaderColumns.Length <= lines.Count && TableHeaderColumns.Select((column, offset) =>
            string.Equals(column, NormalizeTableText(lines[index + offset]), StringComparison.OrdinalIgnoreCase)).All(match => match);

    private static string NormalizeTableText(string value) => Regex.Replace(value.Trim(), @"\s+", " ");

    private static bool TryParseTableRow(IReadOnlyList<string> lines, int index, out ParsedLabValue value)
    {
        value = default!;
        var name = lines[index];
        var current = CurrentResultLine().Match(lines[index + 1]);
        if (!TableAnalyte().IsMatch(name) || !current.Success || !TryParseInvariantDecimal(current.Groups["value"].Value, out var currentValue) ||
            !TryParseInvariantDecimal(lines[index + 2], out _) ||
            !DateOnly.TryParseExact(lines[index + 3], "MM/dd/yyyy", CultureInfo.InvariantCulture, DateTimeStyles.None, out _) ||
            !TableUnit().IsMatch(lines[index + 4])) return false;

        decimal? low = null;
        decimal? high = null;
        var reference = lines[index + 5];
        var bilateral = BilateralRange().Match(reference);
        if (bilateral.Success)
        {
            if (!TryParseInvariantDecimal(bilateral.Groups["low"].Value, out var parsedLow) ||
                !TryParseInvariantDecimal(bilateral.Groups["high"].Value, out var parsedHigh)) return false;
            low = parsedLow;
            high = parsedHigh;
        }
        else if (!UnilateralRange().IsMatch(reference))
        {
            return false;
        }

        value = new ParsedLabValue(name, currentValue, lines[index + 4], low, high);
        return true;
    }

    private static bool TryParseInvariantDecimal(string value, out decimal result)
    {
        result = default;
        return DecimalToken().IsMatch(value) && decimal.TryParse(value, NumberStyles.AllowLeadingSign | NumberStyles.AllowDecimalPoint, CultureInfo.InvariantCulture, out result);
    }

